ntory q hq)\\u27e9\\n\\n/-- A local pairwise coherence fact follows; it does not prove log ordering,\\nfirst-read budgets, memoized sampling laws or the missing inventory. -/\\ntheorem same_address_same_output (Hbytes : Bytes \\u2192 State)\\n    (tr : List (Bytes \\u00d7 State)) (hcons : \\u2200 q \\u2208 tr, q.2 = Hbytes q.1)\\n    (q r : Bytes \\u00d7 State) (hq : q \\u2208 tr) (hr : r \\u2208 tr) (ha : q.1 = r.1) :\\n    q.2 = r.2 := by rw [hcons q hq, hcons r hr, ha]\\n\\n#print axioms prefix_contained\\n#print axioms log_actual\\n#print axioms log_consistent\\n#print axioms every_reached_call\\n#print axioms same_address_same_output\\nend AspisR1PublicPreparation.Tx1DigestLog\\nend\\n\", \"src\": \"NBX_generated/RawTx1DigestLog.lean\", \"obj\": \"/home/dombarker/project-offloads/codex-cx-tx2codec-cache-20261028/RawTx1DigestLog.olean\", \"launchers\": {\"S2W_lean_host.py\": \"from pathlib import Path\\nimport hashlib,json,subprocess,sys\\nB=Path(__file__).resolve().parent;c=B/sys.argv[1];x=json.loads(c.read_text());paths=x['"'"'env'"'"']['"'"'LEAN_PATH'"'"'].split('"'"':'"'"');seen={}\\ndef visit(module):\\n key=module.replace('"'"'.'"'"','"'"'/'"'"')+'"'"'.olean'"'"'\\n if key in seen:return\\n p=next((Path(root)/key for root in paths if (Path(root)/key).is_file()),None)\\n if p is None:raise FileNotFoundError(module)\\n seen[key]=dict(path=str(p),sha256=hashlib.sha256(p.read_bytes()).hexdigest(),bytes=p.stat().st_size)\\n # All imported module dependencies are already inventoried in the inherited S2I\\n # cache packet; the direct import and its split companions are re-pinned here.\\n for suffix in ['"'"'.server'"'"','"'"'.private'"'"','"'"'.ir'"'"']:\\n  q=p.with_suffix('"'"'.ir'"'"') if suffix=='"'"'.ir'"'"' else Path(str(p)+suffix)\\n  if q.exists():seen[str(q)]=dict(path=str(q),sha256=hashlib.sha256(q.read_bytes()).hexdigest(),bytes=q.stat().st_size)\\nfor src in x['"'"'sources'"'"']:\\n for line in (B/src).read_text().splitlines():\\n  if line.startswith(